export class Map {
  constructor() {
    this.mapContainer = document.querySelector('.contacts__map');
    this.mapLoaded = false;

    if (this.mapContainer) {
      this.init();
    }
  }

  init() {
    // Intersection Observer для ленивой загрузки
    if ('IntersectionObserver' in window) {
      const observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && !this.mapLoaded) {
            // Карта видна, можно загружать
            this.loadMap();
            observer.unobserve(entry.target);
          }
        });
      }, {
        rootMargin: '50px',
      });

      observer.observe(this.mapContainer);
    } else {
      // Fallback для старых браузеров
      this.loadMap();
    }
  }

  loadMap() {
    if (this.mapLoaded) {
      return;
    }

    // Создаем скрипт для загрузки карты
    const script = document.createElement('script');
    script.type = 'text/javascript';
    script.charset = 'utf-8';
    script.async = true;
    script.src = 'https://api-maps.yandex.ru/services/constructor/1.0/js/?um=constructor%3A20e8497a73bf6c58f16d0ef9ed3d08c7c3d29cd14b63c690f568914451c029d3&width=100%&height=400&lang=ru_RU&scroll=true';

    // Обработчик успешной загрузки
    script.onload = () => {
      this.mapLoaded = true;
      this.mapContainer.classList.add('loaded');

      // Используем MutationObserver для отслеживания появления iframe
      const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
          if (mutation.type === 'childList') {
            const iframe = this.mapContainer.querySelector('iframe');
            if (iframe) {
              iframe.classList.add('loaded');
              observer.disconnect();
            }
          }
        });
      });

      observer.observe(this.mapContainer, {
        childList: true,
        subtree: true,
      });

      // Fallback - если iframe не появится через 3 секунды
      setTimeout(() => {
        const iframe = this.mapContainer.querySelector('iframe');
        if (iframe) {
          iframe.classList.add('loaded');
        }
        observer.disconnect();
      }, 3000);
    };

    // Обработчик ошибки загрузки
    script.onerror = () => {
      this.mapContainer.classList.add('loaded');
    };

    // Добавляем скрипт в контейнер
    this.mapContainer.appendChild(script);

    // Fallback - скрываем спиннер через 5 секунд
    setTimeout(() => {
      if (!this.mapLoaded) {
        this.mapContainer.classList.add('loaded');
      }
    }, 5000);
  }
}
