export class Loader {
  constructor() {
    this.loader = document.getElementById('loader');
    this.minLoadTime = 1500; // Минимальное время показа лоадера (1.5 сек)
    this.startTime = Date.now();

    if (this.loader) {
      this.init();
    }
  }

  init() {
    // Добавляем класс загрузки для блокировки анимаций
    document.body.classList.add('loading');

    // Блокируем прокрутку при показе лоадера
    document.body.style.overflow = 'hidden';

    // Скрываем лоадер после полной загрузки страницы
    window.addEventListener('load', () => {
      this.hideLoader();
    });

    // Дополнительная проверка через 3 секунды на случай проблем с загрузкой
    setTimeout(() => {
      if (this.loader && !this.loader.classList.contains('hidden')) {
        this.hideLoader();
      }
    }, 3000);
  }

  hideLoader() {
    if (!this.loader) {
      return;
    }

    const elapsedTime = Date.now() - this.startTime;
    const remainingTime = Math.max(0, this.minLoadTime - elapsedTime);

    setTimeout(() => {
      this.loader.classList.add('hidden');

      // Восстанавливаем прокрутку
      document.body.style.overflow = '';

      // Запускаем анимации через 300ms после скрытия лоадера
      setTimeout(() => {
        // Активируем анимации после полного исчезновения лоадера
        document.body.classList.remove('loading');
        document.body.classList.add('loaded');
      }, 300);

      // Удаляем лоадер из DOM после анимации
      setTimeout(() => {
        if (this.loader && this.loader.parentNode) {
          this.loader.parentNode.removeChild(this.loader);
          // Убеждаемся, что лоадер не блокирует взаимодействие
          document.body.style.pointerEvents = '';
        }
      }, 500); // Время анимации из CSS
    }, remainingTime);
  }

  // Метод для принудительного скрытия лоадера (если нужно)
  forceHide() {
    if (this.loader) {
      this.loader.classList.add('hidden');

      // Активируем анимации на сайте
      document.body.classList.remove('loading');
      document.body.classList.add('loaded');

      // Восстанавливаем прокрутку
      document.body.style.overflow = '';
      setTimeout(() => {
        if (this.loader && this.loader.parentNode) {
          this.loader.parentNode.removeChild(this.loader);
        }
      }, 500);
    }
  }
}
